SCHEMA_VERSION = "1"

#: What the final Acceptance hands over. §5.3 names three things, and all three
#: are required: an engagement closed without the operating knowledge has handed
#: over a codebase nobody can run.
HANDOVER_ITEMS = ("codebase", "documentation", "operating_knowledge")

#: The four kinds §8 declares. Closed, and `cut` is deliberately absent -- see
#: the module docstring.
CHANGE_DISPOSITIONS = ("correction", "absorb", "swap", "re-baseline")

#: A correction that interrupts rather than queueing. §8's own examples; a
#: severity outside this set and the routine set is refused rather than guessed,
#: because guessing here decides whether a production outage waits for a Cycle.
CRITICAL_SEVERITIES = ("production-down", "security-breach", "compliance-breach")
ROUTINE_SEVERITIES = ("defect", "regression", "usability", "documentation")

#: Which accountable action each disposition is decided through. All four are
#: the Engagement Lead's; the two that move or exchange commitment are separate
#: actions because `cycle_authority` tiers them as high risk, and a high-risk
#: decision never continues automatically.
_DISPOSITION_ACTION = {
    "correction": "name-change-kind",
    "absorb": "name-change-kind",
    "swap": "approve-swap",
    "re-baseline": "approve-rebaseline",
}


class AcceptanceError(ValueError):
    """An Acceptance or a change disposition this module refuses."""


def _now() -> str:
    return datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")


def _digest(body: Mapping[str, Any]) -> str:
    return "sha256:" + hashlib.sha256(
        json.dumps(body, sort_keys=True, separators=(",", ":"), default=str).encode("utf-8")
    ).hexdigest()


def _parse_ts(raw: object) -> Optional[datetime]:
    text = str(raw or "").strip()
    if not text:
        return None
    if text.endswith("Z"):
        text = text[:-1] + "+00:00"
    try:
        parsed = datetime.fromisoformat(text)
    except ValueError:
        return None
    if parsed.tzinfo is None:
        parsed = parsed.replace(tzinfo=timezone.utc)
    return parsed


# ─── The evidence package ────────────────────────────────────────────────────


def compile_evidence(
    *,
    acceptance_id: str,
    trunk_digest: str,
    opened_at: str,
    cycle_closes: Sequence[Mapping[str, Any]],
    integrated_shas_on_trunk: Sequence[str],
    evidence: Sequence[Mapping[str, Any]] = (),
) -> Dict[str, Any]:
    """One go-live's audit-ready package, keyed on identity plus trunk digest.

    Three refusals, and each is one of `C-15`'s named ones.

        an unintegrated candidate     a Cycle close whose integrated revision
                                      is not observed on this trunk. `The
                                      staging branch must never become the
                                      demonstrated final result`, and a release
                                      compiled from one would be exactly that.
        a fabricated retrospective
        proof                         an evidence record dated after this
                                      Acceptance opened. The package is
                                      compiled from records the work already
                                      produced as it ran; a proof written
                                      afterwards proves the release, not the
                                      work.
        a package that could be
        moved to another release       the package digest covers the Acceptance
                                      identity and the trunk digest, so it
                                      cannot be re-presented for a different
                                      go-live.

    Independent of any one Cycle by construction: `cycle_closes` is a list, and
    nothing here requires a particular one, a particular count, or that no other
    Cycle is open.
    """
    if not str(acceptance_id or "").strip():
        raise AcceptanceError(
            "an Acceptance needs its own identity. Each go-live has its own "
            "package and its own release-readiness decision, and both are keyed "
            "on it -- a release without one cannot be told apart from the last."
        )
    if not str(trunk_digest or "").strip():
        raise AcceptanceError(
            "an Acceptance evaluates a PINNED integrated release candidate, so "
            "it needs the trunk revision it is about. Without one, its approval "
            "is about whatever the trunk happens to be later."
        )
    opened = _parse_ts(opened_at)
    if opened is None:
        raise AcceptanceError(
            "an Acceptance needs the time it opened (%r is not a timestamp). "
            "It is what separates a record the work produced from one written "
            "for the release." % opened_at
        )
    if not cycle_closes:
        raise AcceptanceError(
            "this Acceptance cites no closed Cycle, so there is nothing "
            "integrated for it to release."
        )

    on_trunk = {str(s) for s in integrated_shas_on_trunk or () if s}
    cited: List[Dict[str, Any]] = []
    for close in cycle_closes:
        cycle_id = str((close or {}).get("cycle_id") or "")
        integrated = str((close or {}).get("integrated_sha") or "")
        if not integrated:
            raise AcceptanceError(
                "Cycle %s records no integrated revision, so it is an "
                "UNINTEGRATED candidate. A release compiled from one would "
                "demonstrate a staging branch as the final result."
                % (cycle_id or "<unnamed>")
            )
        if integrated not in on_trunk:
            raise AcceptanceError(
                "Cycle %s integrated %s, which is not observed on the trunk at "
                "%s. Either that work is not in this candidate or this "
                "candidate is not the trunk; both make the package a claim "
                "about something else."
                % (cycle_id, integrated[:12], str(trunk_digest)[:12])
            )
        cited.append({
            "cycle_id": cycle_id,
            "integrated_sha": integrated,
            "trunk_ref": str((close or {}).get("trunk_ref") or ""),
            "closed_at": str((close or {}).get("closed_at") or ""),
        })

    compiled: List[Dict[str, Any]] = []
    for index, record in enumerate(evidence or ()):
        if not isinstance(record, Mapping):
            raise AcceptanceError("evidence entry %d is not a record" % index)
        recorded = _parse_ts(record.get("recorded_at"))
        if recorded is None:
            raise AcceptanceError(
                "evidence %r carries no recorded_at, so it cannot be shown to "
                "predate this Acceptance -- and evidence that cannot be dated "
                "is indistinguishable from evidence written for the release."
                % (record.get("id") or index)
            )
        if recorded > opened:
            raise AcceptanceError(
                "evidence %r was recorded at %s, after this Acceptance opened "
                "at %s. §5.3 compiles the package from records the work already "
                "produced AS IT RAN; a proof produced afterwards is a "
                "retrospective one."
                % (record.get("id") or index, record.get("recorded_at"), opened_at)
            )
        compiled.append(dict(record))

    body = {
        "schema_version": SCHEMA_VERSION,
        "kind": "acceptance.package",
        "acceptance_id": str(acceptance_id).strip(),
        "trunk_digest": str(trunk_digest).strip(),
        "opened_at": str(opened_at),
        "cycles": cited,
        "evidence": compiled,
        "compiled_at": _now(),
    }
    package = dict(body)
    package["package_digest"] = _digest(body)
    return package


# ─── The release-readiness decision ─────────────────────────────────────────


def readiness_decision(
    *,
    package: Mapping[str, Any],
    principal: str,
    outcome: str,
    rationale: str = "",
    produced_by: Optional[str] = None,
) -> Dict[str, Any]:
    """The go-live decision, bound to this package's identity and digest.

    Routed through `cycle_authority`, so it inherits the three refusals that
    make it accountable: an unattributed principal, an actor deciding on its own
    output, and -- because releasing is high risk -- a decision made by the
    automated principal. Release readiness is Quality Assurance's action, and
    the role is derived from the action rather than chosen by the caller.
    """
    acceptance_id = str(package.get("acceptance_id") or "")
    trunk_digest = str(package.get("trunk_digest") or "")
    if not acceptance_id or not trunk_digest:
        raise AcceptanceError(
            "a readiness decision needs a compiled package to be about; this "
            "one names %r at %r" % (acceptance_id, trunk_digest)
        )
    decision = cycle_authority.decide(
        action="decide-release-readiness",
        principal=principal,
        outcome=outcome,
        subject=acceptance_id,
        subject_digest=trunk_digest,
        produced_by=produced_by,
        rationale=rationale,
        factors={
            "package_digest": str(package.get("package_digest") or ""),
            "cycle_ids": [c.get("cycle_id") for c in package.get("cycles") or ()],
        },
    )
    return decision


def assert_decision_binds(
    decision: Mapping[str, Any], *, package: Mapping[str, Any]
) -> None:
    """Refuse an approval reused for another digest, or another go-live.

    The reuse is the failure `C-15` names, and it is a natural one: a release
    slips, the candidate is rebuilt, and the approval from last week is still
    sitting there looking like an approval. It approved a different revision.
    """
    subject = str(decision.get("subject") or "")
    digest = str(decision.get("subject_digest") or "")
    if subject != str(package.get("acceptance_id") or ""):
        raise AcceptanceError(
            "this decision is about Acceptance %r and the package is %r. An "
            "approval belongs to the go-live it was made for."
            % (subject, package.get("acceptance_id"))
        )
    if digest != str(package.get("trunk_digest") or ""):
        raise AcceptanceError(
            "this decision approved trunk %s and the package pins %s. An "
            "approval reused for another digest approved something else -- "
            "rebuild the candidate and decide again."
            % (digest[:12] or "<none>", str(package.get("trunk_digest"))[:12])
        )


# ─── Final versus non-final ─────────────────────────────────────────────────


def handover_recorded(handover: Optional[Mapping[str, Any]]) -> bool:
    """All three of §5.3's items, or it is not a handover.

    An engagement closed without the operating knowledge has handed over a
    codebase nobody can run, which is why this is an AND rather than a count.
    """
    if not isinstance(handover, Mapping):
        return False
    return all(str(handover.get(item) or "").strip() for item in HANDOVER_ITEMS)


def acceptance_target(
    *,
    outstanding_commitments: Sequence[Any],
    handover: Optional[Mapping[str, Any]] = None,
) -> str:
    """Where this Acceptance goes next -- `CYCLE` or `COMPLETE`.

    Delegated to `cycle_lifecycle`, which owns the lifecycle: two answers to
    "does this go-live end the engagement" is how a mid-engagement release
    closes one.
    """
    return cycle_lifecycle.acceptance_target(
        outstanding_commitments=outstanding_commitments,
        handover_recorded=handover_recorded(handover),
    )


def assert_close_permitted(
    *,
    requested_target: str,
    outstanding_commitments: Sequence[Any],
    handover: Optional[Mapping[str, Any]] = None,
) -> None:
    """Refuse a forced terminal close for a non-final release.

    The one direction that needs refusing. A non-final Acceptance returning to
    delivery is the normal case; a non-final Acceptance closing the engagement
    ends it with commitments outstanding and nothing handed over, and the
    predecessor's lifecycle made that the ONLY reachable outcome.
    """
    allowed = acceptance_target(
        outstanding_commitments=outstanding_commitments, handover=handover
    )
    if str(requested_target) == "COMPLETE" and allowed != "COMPLETE":
        missing = [
            item for item in HANDOVER_ITEMS
            if not str((handover or {}).get(item) or "").strip()
        ]
        raise AcceptanceError(
            "this Acceptance cannot close the engagement. Outstanding: %s. "
            "Handover missing: %s. Only the FINAL Acceptance ends the "
            "engagement, and `final` is a property of the engagement's state "
            "rather than a flag a release may set."
            % (", ".join(_commitment_label(c) for c in outstanding_commitments) or "none",
               ", ".join(missing) or "nothing")
        )


def _commitment_label(commitment: Any) -> str:
    """A commitment's description if it is `record_commitment`'s shape, its
    plain value otherwise -- so this refusal names what is owed rather than
    dumping a record's internal fields."""
    if isinstance(commitment, Mapping):
        return str(commitment.get("description") or commitment.get("id") or commitment)
    return str(commitment)


# ─── The four change dispositions ───────────────────────────────────────────


def name_change(
    *,
    disposition: str,
    principal: str,
    subject: str,
    rationale: str = "",
    severity: Optional[str] = None,
    sizing_basis: Optional[str] = None,
    scope_added: Sequence[Mapping[str, Any]] = (),
    scope_removed: Sequence[Mapping[str, Any]] = (),
    baseline_digest_before: object = None,
    baseline_digest_after: object = None,
    client_agreed_at: Optional[str] = None,
    work_started_at: Optional[str] = None,
    new_scope_unit_ids: Sequence[str] = (),
    authorized_unit_ids: Sequence[str] = (),
    produced_by: Optional[str] = None,
) -> Dict[str, Any]:
    """Name one change's kind as an accountable action, or refuse.

    Every branch below asserts what its own disposition promises: the three
    that say "the commitment holds" assert the baseline digest unchanged, and
    the one that moves it requires the client's agreement first. That symmetry
    is the requirement -- §8's four kinds differ only in what they do to the
    commitment, so a disposition that does not check its effect on the
    commitment is a label.
    """
    if str(disposition) in ("cut", "cut-work-unit"):
        raise AcceptanceError(
            "a cut is not a change disposition. It removes unfinished Work "
            "Units INSIDE the baseline and leaves the commitment where it was; "
            "the four kinds are %s. Record it with "
            "`cycle_barrier.record_cut`, which asserts the baseline unchanged."
            % ", ".join(CHANGE_DISPOSITIONS)
        )
    if disposition not in CHANGE_DISPOSITIONS:
        raise AcceptanceError(
            "%r is not one of the four change dispositions (%s). An "
            "unrecognised kind is refused rather than defaulted: the kind is "
            "what says whether the commitment moved."
            % (disposition, ", ".join(CHANGE_DISPOSITIONS))
        )
    if not str(rationale or "").strip():
        raise AcceptanceError(
            "naming a change needs a rationale: the Engagement Lead carries the "
            "disposition to the client, and `it changed` is not a disposition."
        )

    details: Dict[str, Any] = {}

    if disposition == "correction":
        details["severity"] = _validated_severity(severity)
        details["routing"] = (
            "interrupt" if details["severity"] in CRITICAL_SEVERITIES else "next-cycle"
        )
        cycle_barrier.assert_baseline_unchanged(
            baseline_digest_before, baseline_digest_after
        )
    elif disposition == "absorb":
        cycle_barrier.assert_baseline_unchanged(
            baseline_digest_before, baseline_digest_after
        )
    elif disposition == "swap":
        details.update(_validated_swap(sizing_basis, scope_added, scope_removed))
        cycle_barrier.assert_baseline_unchanged(
            baseline_digest_before, baseline_digest_after
        )
    else:  # re-baseline
        details.update(_validated_rebaseline(
            client_agreed_at=client_agreed_at,
            work_started_at=work_started_at,
            baseline_digest_before=baseline_digest_before,
            baseline_digest_after=baseline_digest_after,
            new_scope_unit_ids=new_scope_unit_ids,
            authorized_unit_ids=authorized_unit_ids,
        ))

    decision = cycle_authority.decide(
        action=_DISPOSITION_ACTION[disposition],
        principal=principal,
        outcome="continue",
        subject=subject,
        subject_digest=str(baseline_digest_after or baseline_digest_before or ""),
        produced_by=produced_by,
        rationale=str(rationale).strip(),
        factors=dict(details),
    )
    if decision["role"] != "engagement-lead":
        raise AcceptanceError(
            "disposition %r resolved to role %r; §8 makes naming the change "
            "kind the Engagement Lead's action, and a disposition owned by "
            "anyone else is a scope change nobody answers to the client for."
            % (disposition, decision["role"])
        )
    return {
        "schema_version": SCHEMA_VERSION,
        "kind": "change.disposition",
        "disposition": disposition,
        "subject": str(subject),
        "rationale": str(rationale).strip(),
        "baseline_digest_before": str(baseline_digest_before or ""),
        "baseline_digest_after": str(baseline_digest_after or ""),
        "details": details,
        "decision": decision,
        "named_at": _now(),
    }


def _validated_severity(severity: Optional[str]) -> str:
    known = tuple(CRITICAL_SEVERITIES) + tuple(ROUTINE_SEVERITIES)
    if str(severity or "") not in known:
        raise AcceptanceError(
            "a correction must name its severity (%s); %r is not one of them. "
            "Refused rather than defaulted, because the severity is what "
            "decides whether a production outage waits for a Cycle."
            % (", ".join(known), severity)
        )
    return str(severity)


def _validated_swap(
    sizing_basis: Optional[str],
    scope_added: Sequence[Mapping[str, Any]],
    scope_removed: Sequence[Mapping[str, Any]],
) -> Dict[str, Any]:
    """Equal or smaller, with a recorded basis. Both halves, or it is not a swap.

    Without the basis the comparison is an assertion; without the comparison the
    swap is a re-baseline that nobody negotiated. §8 requires both, and the
    inequality is one-directional on purpose: exchanging for LARGER committed
    work grows the commitment while calling it a swap.
    """
    if not str(sizing_basis or "").strip():
        raise AcceptanceError(
            "a swap must record its sizing basis. Without one, `equal or "
            "smaller` is an assertion rather than a comparison anyone can check "
            "afterwards."
        )
    if not scope_added or not scope_removed:
        raise AcceptanceError(
            "a swap exchanges new scope FOR committed work; it needs both sides "
            "(added=%d, removed=%d). One side alone is an absorb or a cut."
            % (len(scope_added or ()), len(scope_removed or ()))
        )
    added = _sizes("scope_added", scope_added)
    removed = _sizes("scope_removed", scope_removed)
    if sum(added.values()) > sum(removed.values()):
        raise AcceptanceError(
            "this swap adds %s and removes %s. New scope is exchanged for "
            "committed work of EQUAL OR SMALLER size; exchanging for larger "
            "work grows the commitment while calling it a swap, which is a "
            "re-baseline the client never agreed to."
            % (sum(added.values()), sum(removed.values()))
        )
    return {
        "sizing_basis": str(sizing_basis).strip(),
        "added": added,
        "removed": removed,
        "added_size": sum(added.values()),
        "removed_size": sum(removed.values()),
    }


def _sizes(label: str, entries: Sequence[Mapping[str, Any]]) -> Dict[str, float]:
    out: Dict[str, float] = {}
    for index, entry in enumerate(entries):
        if not isinstance(entry, Mapping):
            raise AcceptanceError("%s[%d] is not a {unit_id, size} record" % (label, index))
        unit_id = str(entry.get("unit_id") or "")
        size = entry.get("size")
        if not unit_id:
            raise AcceptanceError("%s[%d] names no unit_id" % (label, index))
        if not isinstance(size, (int, float)) or isinstance(size, bool) or size <= 0:
            raise AcceptanceError(
                "%s entry %s has size %r. A swap is sized, and an unsized or "
                "zero-sized side makes `equal or smaller` unfalsifiable."
                % (label, unit_id, size)
            )
        out[unit_id] = float(size)
    return out


def _validated_rebaseline(
    *,
    client_agreed_at: Optional[str],
    work_started_at: Optional[str],
    baseline_digest_before: object,
    baseline_digest_after: object,
    new_scope_unit_ids: Sequence[str],
    authorized_unit_ids: Sequence[str],
) -> Dict[str, Any]:
    """Agreement first, and already-authorized work keeps running.

    The ordering is the whole requirement: §8 agrees the new scope, timeline and
    cost with the client BEFORE that work begins. A re-baseline recorded after
    the work started is a bill, not an agreement.
    """
    agreed = _parse_ts(client_agreed_at)
    if agreed is None:
        raise AcceptanceError(
            "a re-baseline needs the time the client agreed to the new scope, "
            "timeline and cost (%r is not a timestamp). It is the only thing "
            "that distinguishes an agreement from a bill." % client_agreed_at
        )
    started = _parse_ts(work_started_at)
    if started is not None and started < agreed:
        raise AcceptanceError(
            "the new scope started at %s and the client agreed at %s. "
            "Re-baseline work cannot begin before client agreement: work "
            "already underway makes the negotiation a formality."
            % (work_started_at, client_agreed_at)
        )
    if str(baseline_digest_before or "") == str(baseline_digest_after or ""):
        raise AcceptanceError(
            "this re-baseline leaves the baseline digest at %r. A re-baseline "
            "MOVES the baseline -- one that does not is an absorb, and naming "
            "it a re-baseline records a renegotiation that did not happen."
            % (str(baseline_digest_before or "<none>"))
        )
    overlap = sorted(set(str(u) for u in new_scope_unit_ids)
                     & set(str(u) for u in authorized_unit_ids))
    if overlap:
        raise AcceptanceError(
            "unit(s) %s are already authorized and are also named as new "
            "scope. Existing authorized work CONTINUES while a new baseline is "
            "negotiated; re-scoping committed work is a swap, which has to be "
            "sized and exchanged." % ", ".join(overlap)
        )
    return {
        "client_agreed_at": str(client_agreed_at),
        "work_started_at": str(work_started_at or ""),
        "new_scope_unit_ids": [str(u) for u in new_scope_unit_ids],
        "authorized_unit_ids_continuing": [str(u) for u in authorized_unit_ids],
    }


def assert_new_scope_may_begin(
    *, unit_id: str, change: Optional[Mapping[str, Any]] = None
) -> None:
    """Refuse re-baseline work that no agreed re-baseline covers.

    The other half of the ordering rule. `name_change` refuses a re-baseline
    recorded after the work began; this refuses the work beginning with no
    record at all, which is the same failure arriving from the other side.
    """
    if not isinstance(change, Mapping) or change.get("disposition") != "re-baseline":
        raise AcceptanceError(
            "unit %s is new scope and no agreed re-baseline covers it. A new "
            "scope, timeline and cost are agreed with the client before that "
            "work begins." % unit_id
        )
    covered = [str(u) for u in (change.get("details") or {}).get("new_scope_unit_ids") or ()]
    if str(unit_id) not in covered:
        raise AcceptanceError(
            "unit %s is not in the re-baseline the client agreed to (%s). An "
            "agreement covers the scope it named."
            % (unit_id, ", ".join(covered) or "no units")
        )


def authorized_work_continues(
    *, change: Mapping[str, Any], authorized_unit_ids: Sequence[str]
) -> List[str]:
    """Which already-authorized units keep running during a negotiation.

    All of them, and the function exists to make that checkable rather than
    assumed: `name_change` refuses a re-baseline that names an authorized unit
    as new scope, so by the time a record exists there is nothing here to
    subtract. §8: existing authorized work continues while a new baseline is
    negotiated.
    """
    if change.get("disposition") != "re-baseline":
        return [str(u) for u in authorized_unit_ids]
    named = set(
        str(u) for u in (change.get("details") or {}).get("new_scope_unit_ids") or ()
    )
    return [str(u) for u in authorized_unit_ids if str(u) not in named]


# ─── The absences, proved rather than asserted ──────────────────────────────


def assert_no_fixed_role_fanout() -> None:
    """Acceptance enumerates no roles, and nothing here can be handed a set.

    The predecessor validated exactly five role receipts, so a five-name tuple
    is the shape that would come back first -- as a module constant, or as a
    `required_roles` argument. Both are checked, because the second is how a
    caller reintroduces the first without editing this file.
    """
    offenders: List[str] = []
    for name, value in sorted(globals().items()):
        if name.startswith("_") or not isinstance(value, (list, tuple, frozenset, set)):
            continue
        if name in ("HANDOVER_ITEMS", "CHANGE_DISPOSITIONS", "CRITICAL_SEVERITIES",
                    "ROUTINE_SEVERITIES"):
            continue
        if any(str(v) in cycle_authority.ROLES for v in value):
            offenders.append("constant %s names roles" % name)
    forbidden = ("roles", "required_roles", "role_receipts", "receipts_by_role",
                 "acceptance_roles", "final", "is_final")
    for name, obj in sorted(globals().items()):
        if name.startswith("_") or not inspect.isfunction(obj):
            continue
        if obj.__module__ != __name__:
            continue
        params = inspect.signature(obj).parameters
        for bad in forbidden:
            if bad in params:
                offenders.append("%s(%s=...)" % (name, bad))
    if offenders:
        raise AcceptanceError(
            "Acceptance must be independent of a fixed role fan-out and of a "
            "caller-set `final`: %s. A long engagement ships several times, and "
            "which roles produced the evidence is a property of the work rather "
            "than a checklist the release re-validates. `final` is decided by "
            "`cycle_lifecycle.acceptance_target` from the state of the "
            "engagement." % ", ".join(offenders)
        )
